<span class="line"><span style="color:#A6ACCD;">           </span><span style="color:#F78C6C;">AND</span><span style="color:#A6ACCD;"> her.HZ_APPROVE_STATUS </span><span style="color:#F78C6C;">IN</span><span style="color:#A6ACCD;"> (</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">RUN</span><span style="color:#89DDFF;">&#39;</span><span style="color:#A6ACCD;">,</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">APPROVED</span><span style="color:#89DDFF;">&#39;</span><span style="color:#A6ACCD;">)</span></span>
